# ── When a mean oxidation state is not a state ─────────────────────────────
#
# v1.2.3: _binary_formula_for rounds abs(oxi_state) to pick a binary, and said
# nothing about having done it. On a site shared by two cations the
# occupancy-weighted mean is not an oxidation state at all: Y3NbO7 has Y and
# Nb on one site at a mean of 3.5, rounded up to 4, and the decomposition then
# asked for YO2. Yttrium has no tetravalent oxide because yttrium has no
# tetravalent state.
#
# v1.2.6: the measurement that used to be here was taken over the 30
# structures with a missing binary and claimed an empty band between 0.05 and
# 0.45 of an integer. Re-measured over ALL 29,226 sites in the two families
# there is no empty band anywhere:
#
#     exactly integral   28,218       0.15 to 0.25     136
#     0.002 to 0.05         408       0.25 to 0.35      64
#     0.05  to 0.15         344       0.35 to 0.45      32
#                                     0.45 to 0.50      24
#
# So this is a JUDGEMENT, not a measured gap, and moving it moves the 1.4
# population: 408 sites lie inside it and 600 outside. It is small enough
# that a genuine half-integer mean is never taken for a rounding error,
# which is the whole of what it is for.
OXI_ROUNDING_TOL = 0.05        # e; a mean this far from an integer was not a
                               # state before it was rounded

# ── Looking a structure up ─────────────────────────────────────────────────
#
# v1.2.4: every lookup in this notebook was `df[df['source_cif'] == cif]`,
# which scans the whole frame. Measured on the perovskite run, 938 structures
# and 18,644 per-site rows:
#
#     one scan of the results frame                 2.4 ms
#     one groupby of the same frame                 0.11 s, once
#     one dict lookup afterwards                    0.0000013 ms
#
# About three scans per structure, and the classifier and the
# coordinate-screen count each did their own set, so batch_additivity took
# 5.10 s, classify_additivity 3.67 s and the counting loop 3.50 s.
#
# Group once, pass the index down. Every function that takes one takes it
# optionally and falls back to the scan, so it still works called on its own.
def index_by_cif(df, column='source_cif'):
    """Every row of df, grouped by structure, once."""
    return {k: v for k, v in df.groupby(column, sort=False)}


def rows_for(cif, df, index=None, column='source_cif'):
    """The rows for one structure, from the index if there is one.

    Returns an empty frame where the structure is absent, which is what the
    scan returned, so callers do not change.
    """
    if index is not None:
        got = index.get(cif)
        return got if got is not None else df.iloc[0:0]
    return df[df[column] == cif]


